val appContext = LocalContext.current.applicationContext
val exoPlayer = retain(mediaUri) {
    ExoPlayer.Builder(appContext).build().apply {
        setMediaItem(MediaItem.fromUri(mediaUri))
        prepare()
    }
}
RetainedEffect(exoPlayer) {
    onRetire { exoPlayer.release() }
}

data class RequestContext(
    val tenant: String,
    val traceId: String,
)

context(ctx: RequestContext)
fun loadOrders(): List<Order> =
    repository.findByTenant(ctx.tenant)

fun handle(request: HttpRequest) {
    val ctx = request.toRequestContext()
    with(ctx) {
        loadOrders()
    }
}

