@Composable
fun DetailsRow(
    label: String,
    expanded: Boolean,
    onExpandedChange: (Boolean) -> Unit
) {
    Column {
        Text(text = label, modifier = Modifier.clickable {
            onExpandedChange(!expanded)
        })
        if (expanded) DetailsContent()
    }
}
